// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Return type of the beforeSwap hook.
// Upper 128 bits is the delta in specified tokens. Lower 128 bits is delta in unspecified tokens (to match the afterSwap hook)
type BeforeSwapDelta is int256;

// Creates a BeforeSwapDelta from specified and unspecified
function toBeforeSwapDelta(int128 deltaSpecified, int128 deltaUnspecified)
    pure
    returns (BeforeSwapDelta beforeSwapDelta)
{
    assembly ("memory-safe") {
        beforeSwapDelta := or(shl(128, deltaSpecified), and(sub(shl(128, 1), 1), deltaUnspecified))
    }
}

/// @notice Library for getting the specified and unspecified deltas from the BeforeSwapDelta type
library BeforeSwapDeltaLibrary {
    /// @notice A BeforeSwapDelta of 0
    BeforeSwapDelta public constant ZERO_DELTA = BeforeSwapDelta.wrap(0);

    /// extracts int128 from the upper 128 bits of the BeforeSwapDelta
    /// returned by beforeSwap
    function getSpecifiedDelta(BeforeSwapDelta delta) internal pure returns (int128 deltaSpecified) {
        assembly ("memory-safe") {
            deltaSpecified := sar(128, delta)
        }
    }

    /// extracts int128 from the lower 128 bits of the BeforeSwapDelta
    /// returned by beforeSwap and afterSwap
    function getUnspecifiedDelta(BeforeSwapDelta delta) internal pure returns (int128 deltaUnspecified) {
        assembly ("memory-safe") {
            deltaUnspecified := signextend(15, delta)
        }
    }
}

src/SatoSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IPoolManager} from "v4-core/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "v4-core/interfaces/callback/IUnlockCallback.sol";
import {IERC20Minimal} from "v4-core/interfaces/external/IERC20Minimal.sol";
import {Currency} from "v4-core/types/Currency.sol";
import {PoolKey} from "v4-core/types/PoolKey.sol";
import {SwapParams} from "v4-core/types/PoolOperation.sol";
import {BalanceDelta} from "v4-core/types/BalanceDelta.sol";
import {TickMath} from "v4-core/libraries/TickMath.sol";

/// @title SatoSwapRouter
/// @notice Minimal router that pre-settles the input currency to the PoolManager and then
///         calls swap with the swapper address encoded into hookData. Use this (or a fork)
///         to buy and sell sato through SatoHook.
contract SatoSwapRouter is IUnlockCallback {
    IPoolManager public immutable manager;

    enum Direction { Buy, Sell }

    struct Action {
        Direction direction;
        PoolKey key;
        address swapper;
        address recipient;
        uint256 amountIn;
    }

    error NotManager();
    error TransferFailed();

    constructor(IPoolManager _manager) {
        manager = _manager;
    }

    /// @notice Buy SATO with ETH. Pre-settles `msg.value` to the manager, calls swap,
    ///         takes SATO output for `recipient`. `swapper` is encoded into hookData and
    ///         is the address whose buy-block timestamp is recorded on the hook.
    function buy(PoolKey calldata key, address swapper, address recipient)
        external
        payable
        returns (uint256 satoOut)
    {
        bytes memory data = abi.encode(Action({
            direction: Direction.Buy,
            key: key,
            swapper: swapper,
            recipient: recipient,
            amountIn: msg.value
        }));
        bytes memory ret = manager.unlock(data);
        satoOut = abi.decode(ret, (uint256));
    }

    /// @notice Sell SATO for ETH. Caller must approve this router for at least `satoIn`
    ///         beforehand. `swapper` is recorded on the hook (same-block-as-last-buy
    ///         cooldown applies).
    function sell(PoolKey calldata key, address swapper, address recipient, uint256 satoIn)
        external
        returns (uint256 ethOut)
    {
        IERC20Minimal sato = IERC20Minimal(Currency.unwrap(key.currency1));
        if (!sato.transferFrom(msg.sender, address(this), satoIn)) revert TransferFailed();
        bytes memory data = abi.encode(Action({
            direction: Direction.Sell,
            key: key,
            swapper: swapper,
            recipient: recipient,
            amountIn: satoIn
        }));
        bytes memory ret = manager.unlock(data);
        ethOut = abi.decode(ret, (uint256));
    }

    function unlockCallback(bytes calldata raw) external returns (bytes memory) {
        if (msg.sender != address(manager)) revert NotManager();
        Action memory a = abi.decode(raw, (Action));
        bytes memory hookData = abi.encode(a.swapper);

        if (a.direction == Direction.Buy) {
            manager.settle{value: a.amountIn}();
            BalanceDelta delta = manager.swap(a.key, SwapParams({
                zeroForOne: true,
                amountSpecified: -int256(a.amountIn),
                sqrtPriceLimitX96: TickMath.MIN_SQRT_PRICE + 1
            }), hookData);
            int256 amount1 = delta.amount1();
            uint256 satoOut = uint256(amount1 > 0 ? amount1 : -amount1);
            manager.take(a.key.currency1, a.recipient, satoOut);
            return abi.encode(satoOut);
        } else {
            IERC20Minimal sato = IERC20Minimal(Currency.unwrap(a.key.currency1));
            manager.sync(a.key.currency1);
            if (!sato.transfer(address(manager), a.amountIn)) revert TransferFailed();
            manager.settle();
            BalanceDelta delta = manager.swap(a.key, SwapParams({
                zeroForOne: false,
                amountSpecified: -int256(a.amountIn),
                sqrtPriceLimitX96: TickMath.MAX_SQRT_PRICE - 1
            }), hookData);
            int256 amount0 = delta.amount0();
            uint256 ethOut = uint256(amount0 > 0 ? amount0 : -amount0);
            manager.take(a.key.currency0, a.recipient, ethOut);
            return abi.encode(ethOut);
        }
    }

    receive() external payable {}
}

